import { FileBufferStream, RootLogger } from 'zenlog.js';
    // ...
export default function setup(opt) {
    // ...
    return function metric(setup) {
        setup.debug('option: %o', option);
        const logger = new RootLogger({
            name: setup.core.name,
            instance: `${os.hostname()}-${process.pid}`,
        });
        logger.addStream(new FileBufferStream(option));
        const cpuCount = os.cpus().length;
        const metricRegister = new MetricRegister();
        setup.defineCoreProperty('metricRegister', { value: metricRegister });
        let lastSampleCpuUsage = process.cpuUsage();
        let lastSampleTime = Date.now();
        let requests = 0;
        let requests_slow = 0;
        let requests_time = 0;
        async function collect() {
            const interval = Date.now() - lastSampleTime;
            const cpuUsage = process.cpuUsage(lastSampleCpuUsage);
            // write
            const mem = process.memoryUsage();
            const data = {
                timestamp: Math.round(Date.now() / 1000),
                interval,
                cpu_time: Math.round((cpuUsage.user + cpuUsage.system) / 1000),
                mem_rss: mem.rss,
                mem_heap_total: mem.heapTotal,
                mem_heap_used: mem.heapUsed,
                mem_os_free: os.freemem(),
                os_load: Number((os.loadavg()[0] / cpuCount).toFixed(3)),
                requests,
                requests_slow,
                requests_time,
            };
            // reset
            lastSampleCpuUsage = process.cpuUsage();
            lastSampleTime = Date.now();
            requests = 0;
            requests_slow = 0;
            requests_time = 0;
            await metricRegister.collect(data);
            setup.debug(data);
            // 写入文件
            logger.record(data);
        }
        const timer = setInterval(() => collect(), option.sampleInterval);
        setup.middleware(async function metricMiddleware(ctx, next) {
            requests++;
            const startTime = Date.now();
            try {
                await next();
            }
            finally {
                const elapsed = Date.now() - startTime;
                requests_time += elapsed;
                if (elapsed > option.slowTime) {
                    requests_slow++;
                }
            }
        });
        setup.destroy(async () => {
            clearInterval(timer);
            await logger.close();
        });
    };
}

